+fn assert_posts(world: &World, tag: &str) {
+    let out = nc(tag);
+    let _ = std::fs::remove_file(&out);
+    posting::post_setup(world, &out).unwrap_or_else(|e| panic!("{tag}: a legal mark posts: {e}"));
+    assert!(out.exists(), "{tag}: the program was written");
+    let _ = std::fs::remove_file(&out);
