+/// The operation's own blocking gouge findings (not the program gate's).
+fn op_gouges(ver: &Value) -> usize {
+    ver["findings"]
+        .as_array()
+        .map_or(0, |f| f.iter().filter(|x| x["kind"] == json!("gouge") && x["op"] == json!("E1") && x["blocks_post"] == json!(true)).count())
