+        | OpParams::Offset2D { top_z, bottom_z, stepdown, stepover, .. } => {
+            *top_z = Height::fixed(top);
+            *bottom_z = Height::fixed(bottom);
+            *stepdown = 5.0;
+            *stepover = 4.0;
