+        h.execute(&world, CreateOperation::new(&world, "N1", CUTTER, whole_b(), mark(false, TOP, 1.0)).expect("create"));
+        h.execute(&world, GenerateOperation::new(&world, "N1").expect("generate"));
+        let e = model::find_by_name(&world, "N1").expect("op");
