+#[test]
+fn a_stock_source_hole_or_chamfer_with_no_part_in_the_setup_judges_nothing() {
+    for (label, kind) in [("drill", Kind::Drill), ("bore", Kind::Bore)] {
+        let (world, mut h) = job_without_part(HALF);
