+    }
+}
+
+fn bore(cut: Cut) -> OpParams {
+    OpParams::Bore {
+        links: camcraft_app::links::Links::PLANAR,
+        clearance_z: Height::fixed(25.0),
+        retract_z: None,
+        top_z: Height::fixed(TOP),
+        bottom_z: None,
+        stock_to_leave: 0.0,
+        stepdown: 5.0,
+        feed: 500.0,
+        plunge_feed: 150.0,
+        climb: true,
+        tolerance: 0.01,
+        holes: vec![cut.hole()],
+    }
+}
